for (const notice of Object.values(COLLECTION_NOTICES)) Object.freeze(notice);

const encoder = new TextEncoder();
const decoder = new TextDecoder('utf-8', { fatal: true });
const KEYWORD = 'Stencil Asset Notices';
const KEY_BYTES = encoder.encode(`${KEYWORD}\0`);
const JPEG_KEY_BYTES = encoder.encode(KEYWORD);
const PNG_SIGNATURE = new Uint8Array([137, 80, 78, 71, 13, 10, 26, 10]);
const MAX_RECORD = 16 * 1024;
const MAX_METADATA = 64 * 1024;
const MAX_IMAGE = 6 * 1024 * 1024;
const MAX_EXPORT = 100 * 1024 * 1024;
const MAX_ASSETS = 1000;
const MAX_CHUNKS = 8192;
const cache = new Map();
let cacheSize = 0;
const CRC_TABLE = new Uint32Array(256);
for (let n = 0; n < 256; n++) { let value = n; for (let bit = 0; bit < 8; bit++) value = value & 1 ? 0xedb88320 ^ value >>> 1 : value >>> 1; CRC_TABLE[n] = value >>> 0; }
const fail = () => { throw new Error('The asset credits are damaged or too large. Add the asset again before exporting.'); };
const equal = (a, b) => a.length === b.length && a.every((value, index) => value === b[index]);
const base64 = value => value.length > 0 && value.length % 4 === 0 && /^[a-zA-Z0-9+/]*={0,2}$/.test(value);
const ascii = value => JSON.stringify(value).replace(/[^\x20-\x7e]/g, char => `\\u${char.charCodeAt(0).toString(16).padStart(4, '0')}`);
const plain = value => value && typeof value === 'object' && !Array.isArray(value) && [Object.prototype, null].includes(Object.getPrototypeOf(value));
const fields = (value, expected) => {
  if (!plain(value)) return false;
  const keys = Reflect.ownKeys(value);
  return keys.every(key => typeof key === 'string') && keys.sort().join(',') === [...expected].sort().join(',')
    && keys.every(key => { const property = Object.getOwnPropertyDescriptor(value, key); return property.enumerable && Object.hasOwn(property, 'value'); });
};
const array = (value, max) => Array.isArray(value) && Object.getPrototypeOf(value) === Array.prototype && value.length <= max
  && Reflect.ownKeys(value).length === value.length + 1 && Array.from({ length: value.length }, (_, index) => Object.getOwnPropertyDescriptor(value, index)).every(property => property?.enumerable && Object.hasOwn(property, 'value'));
const crc32 = bytes => { let crc = 0xffffffff; for (const value of bytes) crc = CRC_TABLE[(crc ^ value) & 255] ^ crc >>> 8; return (crc ^ 0xffffffff) >>> 0; };
const join = chunks => { const size = chunks.reduce((sum, chunk) => sum + chunk.length, 0); if (size > MAX_EXPORT) fail(); const result = new Uint8Array(size); let cursor = 0; for (const chunk of chunks) { result.set(chunk, cursor); cursor += chunk.length; } return result; };

function credit(record) {
  if (!fields(record, ['collection', 'license', 'source', 'notice']) || !Object.hasOwn(COLLECTION_NOTICES, record.collection)) fail();
  const expected = COLLECTION_NOTICES[record.collection];
  if (record.license !== expected.license || record.source !== expected.source || record.notice !== expected.notice) fail();
  return { collection: record.collection, license: record.license, source: record.source, notice: record.notice };
}

export function validateAssetNotice(record) {
  if (!fields(record, ['collection', 'id', 'name', 'license', 'source', 'notice'])) fail();
  const approved = credit({ collection: record.collection, license: record.license, source: record.source, notice: record.notice });
  if (typeof record.id !== 'string' || record.id.length > 128 || !new RegExp(`^${approved.collection}-[a-z0-9]+(?:-[a-z0-9]+)*$`).test(record.id)
    || typeof record.name !== 'string' || !record.name.trim() || record.name.length > 100 || /[\x00-\x1f\x7f<>]/.test(record.name)) fail();
  const clean = { collection: approved.collection, id: record.id, name: record.name, license: approved.license, source: approved.source, notice: approved.notice };
  if (encoder.encode(ascii(clean)).length > MAX_RECORD) fail();
  return clean;
}

function uniqueRecords(records) {
  if (!array(records, MAX_ASSETS * 2)) fail();
  const found = new Map();
  for (const record of records) {
    const clean = validateAssetNotice(record), key = `${clean.collection}/${clean.id}`;
    if (found.has(key) && found.get(key).name !== clean.name) fail();
    found.set(key, clean);
    if (found.size > MAX_ASSETS) fail();
  }
  return [...found.values()].sort((a, b) => a.collection.localeCompare(b.collection) || a.id.localeCompare(b.id));
}

function envelope(records) {
  const assets = uniqueRecords(records), credits = new Map();
  for (const record of assets) credits.set(record.collection, credit({ collection: record.collection, license: record.license, source: record.source, notice: record.notice }));
  return { version: 1, credits: [...credits.values()], assets: assets.map(({ collection, id, name }) => ({ collection, id, name })) };
}

function encodeRecords(records) {
  const result = encoder.encode(ascii(envelope(records)));
  if (result.length > MAX_METADATA) fail();
  return result;
}

function decodeRecords(bytes) {
  if (!bytes.length || bytes.length > MAX_METADATA || bytes.some(value => value > 127)) fail();
  let data;
  try { data = JSON.parse(decoder.decode(bytes)); } catch { fail(); }
  if (!fields(data, ['version', 'credits', 'assets']) || data.version !== 1 || !array(data.credits, 3) || !array(data.assets, MAX_ASSETS)) fail();
  const credits = new Map();
  for (const item of data.credits) { const clean = credit(item); if (credits.has(clean.collection)) fail(); credits.set(clean.collection, clean); }
  const hydrated = data.assets.map(item => {
    if (!fields(item, ['collection', 'id', 'name']) || !credits.has(item.collection)) fail();
    return { ...credits.get(item.collection), id: item.id, name: item.name };
  });
  const result = uniqueRecords(hydrated);
  if (result.length !== hydrated.length || [...credits.keys()].some(collection => !result.some(item => item.collection === collection))) fail();
  return result;
}

function pngChunks(bytes, validateCRC = true) {
  if (!(bytes instanceof Uint8Array) || bytes.length < 45 || bytes.length > MAX_EXPORT || !equal(bytes.subarray(0, 8), PNG_SIGNATURE)) fail();
  const view = new DataView(bytes.buffer, bytes.byteOffset, bytes.byteLength), chunks = [];
  let cursor = 8, sawData = false, endedData = false;
  while (cursor < bytes.length) {
    if (chunks.length >= MAX_CHUNKS) fail();
    if (cursor + 12 > bytes.length) fail();
    const length = view.getUint32(cursor), end = cursor + length + 12;
    if (end > bytes.length) fail();
    const type = String.fromCharCode(...bytes.subarray(cursor + 4, cursor + 8));
    if (!/^[A-Za-z]{4}$/.test(type) || type[2] !== type[2].toUpperCase()) fail();
    const data = bytes.subarray(cursor + 8, end - 4);
    if (validateCRC && crc32(bytes.subarray(cursor + 4, end - 4)) !== view.getUint32(end - 4)) fail();
    if (!chunks.length && (type !== 'IHDR' || length !== 13)) fail();
    if (type === 'IHDR') {
      if (chunks.length || length !== 13) fail();
      const width = view.getUint32(cursor + 8), height = view.getUint32(cursor + 12), depth = data[8], colour = data[9];
      const validDepths = { 0: [1, 2, 4, 8, 16], 2: [8, 16], 3: [1, 2, 4, 8], 4: [8, 16], 6: [8, 16] };
      if (!width || !height || width > 16384 || height > 16384 || width * height > 40000000 || !validDepths[colour]?.includes(depth) || data[10] || data[11] || data[12] > 1) fail();
    }
    if (type === 'IDAT') { if (endedData) fail(); sawData = true; }
    else if (sawData && type !== 'IEND') endedData = true;
    if (type[0] === type[0].toUpperCase() && !['IHDR', 'PLTE', 'IDAT', 'IEND'].includes(type)) fail();
    const notice = type === 'tEXt' && data.length >= KEY_BYTES.length && equal(data.subarray(0, KEY_BYTES.length), KEY_BYTES);
    chunks.push({ type, data, notice, raw: bytes.subarray(cursor, end) });
    cursor = end;
    if (type === 'IEND') { if (length || !sawData || cursor !== bytes.length) fail(); return chunks; }
  }
  fail();
}

function pngNotices(chunks) {
  const found = chunks.filter(chunk => chunk.notice);
  if (found.length > 1) fail();
  return found.length ? decodeRecords(found[0].data.subarray(KEY_BYTES.length)) : [];
}

function makePNGChunk(type, data) {
  const result = new Uint8Array(data.length + 12), view = new DataView(result.buffer);
  view.setUint32(0, data.length); result.set(encoder.encode(type), 4); result.set(data, 8);
  view.setUint32(result.length - 4, crc32(result.subarray(4, result.length - 4)));
  return result;
}

function appendPNG(bytes, records) {
  const chunks = pngChunks(bytes), all = uniqueRecords([...pngNotices(chunks), ...records]);
  const output = [PNG_SIGNATURE];
  for (const chunk of chunks) {
    if (chunk.notice) continue;
    if (chunk.type === 'IEND' && all.length) output.push(makePNGChunk('tEXt', join([KEY_BYTES, encodeRecords(all)])));
    output.push(chunk.raw);
  }
  return join(output);
}

export function embedAssetNotice(png, record) {
  if (!(png instanceof Uint8Array) || png.length > MAX_IMAGE) fail();
  const result = appendPNG(png, [validateAssetNotice(record)]);
  if (result.length > MAX_IMAGE) fail();
  return result;
}

function jpegSegments(bytes) {
  if (!(bytes instanceof Uint8Array) || bytes.length < 4 || bytes.length > MAX_EXPORT || bytes[0] !== 255 || bytes[1] !== 216) fail();
  const segments = []; let cursor = 2;
  while (cursor < bytes.length) {
    if (segments.length >= MAX_CHUNKS) fail();
    const start = cursor;
    if (bytes[cursor++] !== 255) fail();
    while (bytes[cursor] === 255) cursor++;
    const marker = bytes[cursor++];
    if (!marker || marker === undefined || marker === 216 || marker >= 208 && marker <= 215) fail();
    if (marker === 217) { if (cursor !== bytes.length) fail(); segments.push({ raw: bytes.subarray(start, cursor), data: null }); return segments; }
    if (marker === 1) { segments.push({ raw: bytes.subarray(start, cursor), data: null }); continue; }
    if (cursor + 2 > bytes.length) fail();
    const length = bytes[cursor] * 256 + bytes[cursor + 1], end = cursor + length;
    if (length < 2 || end > bytes.length) fail();
    const data = bytes.subarray(cursor + 2, end);
    segments.push({ marker, data, raw: bytes.subarray(start, end) }); cursor = end;
    if (marker === 218) {
      const scanStart = cursor;
      while (cursor < bytes.length) {
        if (bytes[cursor] !== 255) { cursor++; continue; }
        let next = cursor + 1; while (bytes[next] === 255) next++;
        if (bytes[next] === 0 || bytes[next] >= 208 && bytes[next] <= 215) { cursor = next + 1; continue; }
        break;
      }
      if (cursor >= bytes.length) fail();
      if (segments.length >= MAX_CHUNKS) fail();
      segments.push({ raw: bytes.subarray(scanStart, cursor), data: null });
    }
  }
  fail();
}

function jpegNotice(segment) {
  if (segment.marker !== 254 || segment.data.length < KEYWORD.length) return null;
  if (!equal(segment.data.subarray(0, JPEG_KEY_BYTES.length), JPEG_KEY_BYTES)) return null;
  const beginning = String.fromCharCode(...segment.data.subarray(0, Math.min(segment.data.length, 40)));
  const header = beginning.match(/^Stencil Asset Notices ([12])\/([12])\n/);
  if (!header || Number(header[1]) > Number(header[2])) fail();
  return { index: Number(header[1]), total: Number(header[2]), data: segment.data.subarray(header[0].length) };
}

function jpegNotices(segments) {
  const notices = segments.map(jpegNotice).filter(Boolean);
  if (notices.length) {
    const count = notices[0].total;
    if (notices.length !== count || notices.some((item, index) => item.total !== count || item.index !== index + 1)) fail();
    return decodeRecords(join(notices.map(item => item.data)));
  }
  return [];
}

function appendJPEG(bytes, records) {
  const segments = jpegSegments(bytes), previous = jpegNotices(segments);
  const all = uniqueRecords([...previous, ...records]), output = [bytes.subarray(0, 2)];
  if (all.length) {
    const encoded = encodeRecords(all), total = Math.ceil(encoded.length / 60000);
    for (let index = 0; index < total; index++) {
      const data = join([encoder.encode(`${KEYWORD} ${index + 1}/${total}\n`), encoded.subarray(index * 60000, (index + 1) * 60000)]);
      const chunk = new Uint8Array(data.length + 4); chunk.set([255, 254, (data.length + 2) >>> 8, (data.length + 2) & 255]); chunk.set(data, 4); output.push(chunk);
    }
  }
  for (const segment of segments) if (!jpegNotice(segment)) output.push(segment.raw);
  return join(output);
}

export function appendExportNotices(bytes, type, records) {
  const clean = uniqueRecords(records);
  if (type === 'image/png') return appendPNG(bytes, clean);
  if (type === 'image/jpeg') return appendJPEG(bytes, clean);
  throw new Error('Asset credits can be saved in PNG or JPEG images.');
}

function readElementNotices(src) {
  if (typeof src !== 'string') return [];
  const prefix = src.startsWith('data:image/png;base64,') ? 'data:image/png;base64,' : src.startsWith('data:image/jpeg;base64,') ? 'data:image/jpeg;base64,' : null;
  if (!prefix || src.length > Math.ceil(MAX_IMAGE / 3) * 4 + prefix.length) return [];
  if (cache.has(src)) { const result = cache.get(src); cache.delete(src); cache.set(src, result); return structuredClone(result); }
  let bytes;
  try {
    const encoded = src.slice(prefix.length);
    if (!base64(encoded)) return [];
    const binary = atob(encoded); bytes = Uint8Array.from(binary, value => value.charCodeAt(0));
  } catch { return []; }
  let result = [], parts;
  const isPNG = prefix === 'data:image/png;base64,';
  try { parts = isPNG ? pngChunks(bytes, false) : jpegSegments(bytes); } catch {
    // Read the bounded image bytes without creating chunk objects. Credits
    // beyond a broken header or the structural cap must not silently vanish.
    const marker = isPNG ? KEY_BYTES : JPEG_KEY_BYTES;
    for (let cursor = 0; cursor + marker.length <= bytes.length; cursor++) {
      if (bytes[cursor] === marker[0] && equal(bytes.subarray(cursor, cursor + marker.length), marker)) fail();
    }
    return [];
  }
  if (isPNG) { if (parts.some(chunk => chunk.notice)) result = pngNotices(pngChunks(bytes)); }
  else result = jpegNotices(parts);
  if (src.length <= 12 * 1024 * 1024) {
    while (cache.size >= 32 || cacheSize + src.length > 12 * 1024 * 1024) { const oldest = cache.keys().next().value; cacheSize -= oldest.length; cache.delete(oldest); }
    cache.set(src, result); cacheSize += src.length;
  }
  return structuredClone(result);
}

export function collectAssetNotices(elements) {
  if (!array(elements, MAX_ASSETS)) fail();
  let records = [];
  for (const element of elements) if (['image', 'frame'].includes(element?.type)) records = uniqueRecords([...records, ...readElementNotices(element.src)]);
  return records;
}

export function preserveAssetNoticesDataURI(originalSrc, nextPNGsrc) {
  const records = collectAssetNotices([{ type: 'image', src: originalSrc }]);
  if (!records.length) return nextPNGsrc;
  if (typeof nextPNGsrc !== 'string' || !nextPNGsrc.startsWith('data:image/png;base64,') || nextPNGsrc.length > Math.ceil(MAX_IMAGE / 3) * 4 + 22) fail();
  let bytes;
  try {
    const encoded = nextPNGsrc.slice(22);
    if (!base64(encoded)) fail();
    bytes = Uint8Array.from(atob(encoded), value => value.charCodeAt(0));
  } catch { fail(); }
  const output = appendExportNotices(bytes, 'image/png', records);
  if (output.length > MAX_IMAGE) fail();
  const parts = [];
  for (let cursor = 0; cursor < output.length; cursor += 32768) parts.push(String.fromCharCode(...output.subarray(cursor, cursor + 32768)));
  return `data:image/png;base64,${btoa(parts.join(''))}`;
}

export function assetCredits(elements) {
  const credits = new Map();
  for (const record of collectAssetNotices(elements)) credits.set(record.collection, credit({ collection: record.collection, license: record.license, source: record.source, notice: record.notice }));
  return [...credits.values()];
}

export function assetMetadataXML(elements) {
  const records = collectAssetNotices(elements);
  if (!records.length) return '';
  const escaped = decoder.decode(encodeRecords(records)).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;').replace(/'/g, '&apos;');
  return `<metadata id="stencil-asset-notices">${escaped}</metadata>`;
}
